def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    desperate_count = 0
    rich_count = 0
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('budget', 0) >= 120:
                rich_count += 1
            if opp.get('hp', 10) <= 4 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    severe_need = hp <= 3 or no_water >= 2
    urgent_need = hp <= 5 or no_water >= 1

    low_supply = supply <= 16
    high_supply = supply >= 22

    if severe_need:
        target = max(78.0, highest_prev + 4.0)
        if low_supply:
            target = max(target, 96.0)
        return float(min(budget, target))

    if urgent_need:
        if highest_prev >= 110:
            target = 72.0 if not low_supply else 88.0
        else:
            target = max(62.0, highest_prev + 2.0)
            if low_supply:
                target += 10.0
        return float(min(budget, target))

    if high_supply:
        if highest_prev >= 120:
            target = 16.0
        elif highest_prev >= 90:
            target = 24.0
        else:
            target = max(18.0, avg_prev * 0.28)
        return float(min(budget, target))

    if low_supply:
        if desperate_count >= 2 and highest_prev >= 100:
            target = 38.0
        else:
            target = max(44.0, highest_prev + 1.5)
            if rich_count >= 2:
                target += 6.0
        return float(min(budget, target))

    if highest_prev >= 130:
        target = 22.0
    elif highest_prev >= 100:
        target = 34.0
    elif highest_prev >= 70:
        target = highest_prev + 1.5
    else:
        target = max(28.0, avg_prev * 0.55 if avg_prev > 0 else 30.0)

    if day >= 8 and hp >= 7 and budget < 140:
        target *= 0.85

    return float(min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 50.0

    if my_status['hp'] < 4:
        bid = min(my_status['budget'], avg_prev_bid * 1.1)
    elif day_context['supply'] < 18:
        bid = min(my_status['budget'], avg_prev_bid * 0.95)
    else:
        bid = min(my_status['budget'], avg_prev_bid * 0.7)

    return max(0.0, float(bid))
